69	// memoryOperationReceipt is the versioned mutation receipt: operation
70	// identity, per-artifact prior/new states, stable codes; never content.
71	type memoryOperationReceipt struct {
72		SchemaVersion int                     `json:"schema_version"`
73		OperationID   string                  `json:"operation_id"`
74		Operation     string                  `json:"operation"`
75		DryRun        bool                    `json:"dry_run,omitempty"`
76		StartedAt     time.Time               `json:"started_at"`
77		FinishedAt    time.Time               `json:"finished_at"`
78		Artifacts     []memoryReceiptArtifact `json:"artifacts"`
79		ErrorCode     string                  `json:"error_code,omitempty"`
80		SessionRef    string                  `json:"session_ref,omitempty"`
81		JobIDs        []string                `json:"job_ids,omitempty"`
82	}
