90	func newMemoryOperationReceipt(operation string, now time.Time) memoryOperationReceipt {
91		h := sha256.New()
92		h.Write([]byte(operation))
93		h.Write([]byte{0})
94		h.Write([]byte(now.UTC().Format(time.RFC3339Nano)))
95		return memoryOperationReceipt{
96			SchemaVersion: memoryOperationReceiptSchemaVersion,
97			OperationID:   "op:" + hex.EncodeToString(h.Sum(nil))[:16],
98			Operation:     operation,
99			StartedAt:     now,
100			Artifacts:     []memoryReceiptArtifact{},
101		}
102	}
103	
104	// finalizeMemoryOperationReceipt closes a receipt and canonicalizes its
105	// collection fields before either output mode observes it. Mutation commands
106	// may discover artifacts incrementally, but their receipts must not depend on
107	// directory iteration order or selector spelling.
108	func finalizeMemoryOperationReceipt(receipt *memoryOperationReceipt, now time.Time) {
109		if receipt == nil {
110			return
111		}
112		receipt.FinishedAt = now.UTC()
113		if receipt.Artifacts == nil {
114			receipt.Artifacts = []memoryReceiptArtifact{}
115		}
116		sort.SliceStable(receipt.Artifacts, func(i, j int) bool {
117			if receipt.Artifacts[i].Path != receipt.Artifacts[j].Path {
118				return receipt.Artifacts[i].Path < receipt.Artifacts[j].Path
119			}
120			if receipt.Artifacts[i].PriorState != receipt.Artifacts[j].PriorState {
121				return receipt.Artifacts[i].PriorState < receipt.Artifacts[j].PriorState
122			}
123			return receipt.Artifacts[i].NewState < receipt.Artifacts[j].NewState
124		})
125		sort.Strings(receipt.JobIDs)
126		if len(receipt.JobIDs) > 1 {
127			unique := receipt.JobIDs[:1]
128			for _, jobID := range receipt.JobIDs[1:] {
129				if jobID != unique[len(unique)-1] {
130					unique = append(unique, jobID)
131				}
132			}
133			receipt.JobIDs = unique
134		}
135	}
