15	func executeMemoryCommandWithFailOnce(t *testing.T, cmd *cobra.Command, args ...string) (string, error) {
16		t.Helper()
17		writer := &failOnceMemoryReceiptWriter{}
18		cmd.SilenceErrors, cmd.SilenceUsage = true, true
19		cmd.SetOut(writer)
20		cmd.SetErr(&strings.Builder{})
21		cmd.SetArgs(args)
22		err := cmd.Execute()
23		return writer.output.String(), err
24	}
