27		assertReceipt := func(t *testing.T, out, operation, legacyResult string) {
28			t.Helper()
29			if strings.Contains(out, "{") || !strings.Contains(out, operation+" completed ") ||
30				!strings.Contains(out, "schema_version=1") || !strings.Contains(out, "operation_id=op:") ||
31				!strings.Contains(out, "finished_at=") || !strings.Contains(out, legacyResult) {
32				t.Fatalf("%s plain success receipt = %q", operation, out)
